"use client";

import { cn } from "@/lib/utils";
import { cva, type VariantProps } from "class-variance-authority";
import { Slot } from "radix-ui";
import type * as React from "react";

/**
 * Badge (badge-radix)
 *
 * A compact label with two independent axes: a visual treatment (solid, soft, outline, ghost, link) and a semantic tone for status color.
 *
 * Exports: Badge, badgeVariants
 *
 * Props:
 * - Badge: React.ComponentProps<"span"> & VariantProps<typeof badgeVariants> & { asChild?: boolean }
 *   - variant: "solid" | "soft" | "outline" | "ghost" | "link" (default "solid"). Selects the variant styles defined by badgeVariants.
 *   - tone: "neutral" | "accent" | "success" | "warning" | "info" | "destructive" (default "neutral"). Selects the tone styles defined by badgeVariants.
 *   - asChild: boolean (default false). Render the single child element instead of the default element, merging props onto it (Radix Slot).
 *
 * Theme tokens (shadcn names, from your theme): --accent, --accent-foreground, --border, --destructive, --foreground, --primary, --primary-foreground, --ring, --secondary, --secondary-foreground.
 * Component variables (shipped in this item's cssVars, light and dark): --badge-destructive-foreground, --badge-info, --badge-info-foreground, --badge-success, --badge-success-foreground, --badge-warning, --badge-warning-foreground.
 *
 * Accessibility:
 * - Renders an inline span, so its text is read with the surrounding content; keep the label meaningful without its color.
 * - Tone is never the only signal: the label carries the meaning, and every tone keeps readable text contrast.
 * - Rendered as a link through asChild, it shows a visible focus ring.
 *
 * Customize:
 * - variant picks the treatment and tone picks the semantic color; any pair composes without new variants.
 * - Status colors come from --success, --warning, and --info, which ship with this item; change their values in your theme.
 * - Add a tone by extending the tone axis and adding one compound variant per treatment.
 */

const badgeVariants = cva(
  "inline-flex w-fit shrink-0 items-center justify-center gap-1 overflow-hidden whitespace-nowrap rounded-full border border-transparent px-2 py-0.5 font-medium text-xs tabular-nums transition-[color,box-shadow] focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&>svg]:pointer-events-none [&>svg]:size-3",
  {
    variants: {
      variant: {
        solid: "",
        soft: "",
        outline: "",
        ghost: "",
        link: "text-primary underline-offset-4 [a&]:hover:underline",
      },
      tone: {
        neutral: "",
        accent: "",
        success: "",
        warning: "",
        info: "",
        destructive: "",
      },
    },
    compoundVariants: [
      {
        variant: "solid",
        tone: "neutral",
        className:
          "bg-primary text-primary-foreground [a&]:hover:bg-primary/90",
      },
      {
        variant: "solid",
        tone: "accent",
        className: "bg-accent text-accent-foreground [a&]:hover:bg-accent/90",
      },
      {
        variant: "solid",
        tone: "success",
        className:
          "bg-(--badge-success) text-(--badge-success-foreground) [a&]:hover:bg-(--badge-success)/90",
      },
      {
        variant: "solid",
        tone: "warning",
        className:
          "bg-(--badge-warning) text-(--badge-warning-foreground) [a&]:hover:bg-(--badge-warning)/90",
      },
      {
        variant: "solid",
        tone: "info",
        className: "bg-(--badge-info) text-(--badge-info-foreground) [a&]:hover:bg-(--badge-info)/90",
      },
      {
        variant: "solid",
        tone: "destructive",
        className:
          "bg-destructive text-(--badge-destructive-foreground) focus-visible:ring-destructive/20 dark:bg-destructive/60 dark:focus-visible:ring-destructive/40 [a&]:hover:bg-destructive/90",
      },
      {
        variant: "soft",
        tone: "neutral",
        className:
          "bg-secondary text-secondary-foreground [a&]:hover:bg-secondary/90",
      },
      {
        variant: "soft",
        tone: "accent",
        className: "bg-accent/15 text-accent [a&]:hover:bg-accent/25",
      },
      {
        variant: "soft",
        tone: "success",
        className: "bg-(--badge-success)/15 text-(--badge-success) [a&]:hover:bg-(--badge-success)/25",
      },
      {
        variant: "soft",
        tone: "warning",
        className: "bg-(--badge-warning)/15 text-(--badge-warning) [a&]:hover:bg-(--badge-warning)/25",
      },
      {
        variant: "soft",
        tone: "info",
        className: "bg-(--badge-info)/15 text-(--badge-info) [a&]:hover:bg-(--badge-info)/25",
      },
      {
        variant: "soft",
        tone: "destructive",
        className:
          "bg-destructive/15 text-destructive [a&]:hover:bg-destructive/25",
      },
      {
        variant: "outline",
        tone: "neutral",
        className:
          "border-border text-foreground [a&]:hover:bg-accent [a&]:hover:text-accent-foreground",
      },
      {
        variant: "outline",
        tone: "accent",
        className: "border-accent/40 text-accent",
      },
      {
        variant: "outline",
        tone: "success",
        className: "border-(--badge-success)/40 text-(--badge-success)",
      },
      {
        variant: "outline",
        tone: "warning",
        className: "border-(--badge-warning)/40 text-(--badge-warning)",
      },
      {
        variant: "outline",
        tone: "info",
        className: "border-(--badge-info)/40 text-(--badge-info)",
      },
      {
        variant: "outline",
        tone: "destructive",
        className: "border-destructive/40 text-destructive",
      },
      {
        variant: "ghost",
        tone: "neutral",
        className: "[a&]:hover:bg-accent [a&]:hover:text-accent-foreground",
      },
      { variant: "ghost", tone: "accent", className: "text-accent" },
      { variant: "ghost", tone: "success", className: "text-(--badge-success)" },
      { variant: "ghost", tone: "warning", className: "text-(--badge-warning)" },
      { variant: "ghost", tone: "info", className: "text-(--badge-info)" },
      {
        variant: "ghost",
        tone: "destructive",
        className: "text-destructive",
      },
    ],
    defaultVariants: {
      variant: "solid",
      tone: "neutral",
    },
  }
);

function Badge({
  className,
  variant = "solid",
  tone = "neutral",
  asChild = false,
  ...props
}: React.ComponentProps<"span"> &
  VariantProps<typeof badgeVariants> & { asChild?: boolean }) {
  const Comp = asChild ? Slot.Root : "span";

  return (
    <Comp
      className={cn(badgeVariants({ variant, tone }), className)}
      data-slot="badge"
      data-tone={tone}
      data-variant={variant}
      {...props}
    />
  );
}

export { Badge, badgeVariants };
